import { defineSchema, defineTable } from "convex/server";
import { v } from "convex/values";

export default defineSchema({
  webhooks: defineTable({
    payload: v.string(),
    runId: v.string(),
  }).index("by_runId", ["runId"]),
});

import { internalMutation } from "convex/server";
import { v } from "convex/values";

export const insertWebhook = internalMutation({
  args: {
    payload: v.string(),
    runId: v.string(),
  },
  handler: async (ctx, { payload, runId }) => {
    await ctx.db.insert("webhooks", { payload, runId });
  },
});

import { query } from "convex/server";
import { v } from "convex/values";

export const get_webhook = query({
  args: {
    runId: v.string(),
  },
  handler: async (ctx, { runId }) => {
    return await ctx.db
      .query("webhooks")
      .withIndex("by_runId", (q) => q.eq("runId", runId))
      .collect();
  },
});

import { httpAction } from "convex/server";
import { httpRouter } from "convex/server";
import { internal } from "convex/_generated/api";

const http = httpRouter();

http.route({
  path: "/webhook",
  method: "POST",
  handler: httpAction(async (ctx, request) => {
    let body: unknown;
    try {
      body = await request.json();
    } catch (error) {
      return new Response("Invalid JSON", { status: 400 });
    }

    if (
      typeof body !== "object" ||
      body === null ||
      !("payload" in body) ||
      !("runId" in body) ||
      typeof (body as { payload: unknown }).payload !== "string" ||
      typeof (body as { runId: unknown }).runId !== "string"
    ) {
      return new Response("Invalid payload", { status: 400 });
    }

    const { payload, runId } = body as { payload: string; runId: string };

    await ctx.runMutation(internal.webhooksInternal.insertWebhook, {
      payload,
      runId,
    });

    return new Response("OK", { status: 200 });
  }),
});

export default http;

